var builder = new StreamsBuilder();

KStream<String, OrderPlaced> orders = builder.stream("order.placed.v1");

orders
    .filter((k, v) -> v.amount() >= 10_000)
    .mapValues(v -> new BigOrder(v.orderId(), v.amount(), v.memberId()))
    .to("order.big.v1");

var props = new Properties();
props.put(StreamsConfig.APPLICATION_ID_CONFIG, "order-processor");   // = group.id
props.put(StreamsConfig.BOOTSTRAP_SERVERS_CONFIG, "localhost:9092");
props.put(StreamsConfig.PROCESSING_GUARANTEE_CONFIG,
          StreamsConfig.EXACTLY_ONCE_V2);                            // 8.4절

var streams = new KafkaStreams(builder.build(), props);
Runtime.getRuntime().addShutdownHook(new Thread(streams::close));
streams.start();
